// Set to true when the folder you are operating in is a source-control repository (for example a Git working directory); set to false otherwise. You must populate this field. Defaults to false.
is_repository?: boolean, // default: false
// Maximum number of users to return. Range: 1-50. Default: 10.
limit?: integer, // default: 10, minimum: 1, maximum: 50
// Text to match against users in the organization, typically a name (for example 'Jane Doe', 'jane') or an email / email prefix (for example 'jane.doe@'). Must not be empty.
query: string, // minLength: 1
}): Promise<// Users matching an organization user search, scoped to the caller's org.
{
// Matching users, ordered by search relevance.
users?: Array<
// A single user returned by an organization user search.
{
// User's email address.
email: string,
// Unique user identifier.
id: string,
// User's display name.
name: string,
}
>,
}>;
```

