// The type of search to perform. Valid values: BOARD, DOCUMENTS, FOLDERS, WORKSPACES, UPDATES, ITEMS, TIMELINE_ITEMS, DASHBOARDS.
searchType: "BOARD" | "DOCUMENTS" | "FOLDERS" | "WORKSPACES" | "UPDATES" | "ITEMS" | "TIMELINE_ITEMS" | "DASHBOARDS",
// Filter (ITEMS only): status labels (e.g. "Done", "Stuck"). Matches items where any of their status columns has one of these labels — every status-type column of the item is checked, not one specific column, including columns titled e.g. "Label" or "Priority", which are status columns too. Whole-label match, ignoring case. At most 10 labels. Values are alternatives (any of); all provided filters must be satisfied (AND). Only pass it if the user explicitly asked to filter by status. Example: ["Done", "Stuck"].
// maxItems: 10
statusLabels?: Array<
string // minLength: 1, maxLength: 64
>,
// Search strategy, trading result quality against latency. SPEED: keyword matching only — no semantic retrieval, no reranking; fastest. BALANCED (used when omitted): keyword and semantic retrieval fused together. QUALITY: BALANCED plus AI reranking of the results; slowest. Start with SPEED and escalate to BALANCED, then QUALITY, only when it returns no or clearly irrelevant results. Every strategy — SPEED most of all — favors short, keyword-based search terms: most terms must match, so extra words cut results. Prefer several focused searches over one long one. Applies to BOARD, ITEMS, DOCUMENTS, UPDATES, DASHBOARDS search; ignored for other searchTypes.
strategy?: "SPEED" | "BALANCED" | "QUALITY",
// Filter (ITEMS only): tag names (e.g. "bug", "q3-launch"). Matches items tagged with any of these tags — every tags column of the item is checked, not one specific column. Whole-name match, ignoring case; a leading "#" is ignored. At most 10 tags. Values are alternatives (any of); all provided filters must be satisfied (AND). Only pass it if the user explicitly asked to filter by tags. Example: ["bug", "urgent"].
// maxItems: 10
tagNames?: Array<
string // minLength: 1, maxLength: 64
>,
// Filter (ITEMS only): team IDs (numbers). Matches items with any of these teams assigned in any of their people columns — every person and team column of the item is checked, not one specific column. At most 50 unique IDs in total across personIds and teamIds. Values are alternatives (any of); all provided filters must be satisfied (AND). Only pass it if the user explicitly asked to filter by assigned teams. Example: [12345].
teamIds?: number[],
// Filter TIMELINE_ITEMS search by timeline item type, e.g. "email", "note", "meeting", "phoneCall". Only applies to TIMELINE_ITEMS search.
timelineItemType?: "email" | "googleCalendar" | "outlookCalendar" | "zoom" | "activity" | "custom" | "note" | "videoMeeting" | "phoneCall" | "chatWindow" | "meeting" | "aiAssistant" | "aiReply" | "portal" | "demoEmail" | "aiSummary" | "form" | "portfolio_status" | "sequencesEmail" | "outreachExpertPhoneCall" | "outreachExpertPhoneCallV2" | "mergedTickets" | "customInternalApp" | "campaigns",
