// Required unless every update sets its own boardId. The id of the board that contains the items, used for every update that does not set its own boardId. For a subitem, this is the subitems board, not the parent item's board: get it from the parent board's subitems column via get_board_info.
boardId?: number,
// The item updates to apply, up to 40 per call. Each entry updates one item and returns its own result on success or a raw error message on failure. Each entry independently chooses its boardId, columnValues, and createLabelsIfMissing.
// minItems: 1, maxItems: 40
updates: Array<
{
// Required unless the batch-level boardId is set. The id of the board that contains this item. Set it to target a different board than the batch boardId. For a subitem, this is the subitems board, not the parent item's board: get it from the parent board's subitems column via get_board_info.
boardId?: number,
// The new column values for this item, keyed by column id. Defaults to "{}" (no column values). To change the item name include a "name" key. Pass a JSON object serialized once as a string, keyed by column id — not a JSON string of a JSON string. Column ids and labels must come from get_board_info for this board, people ids from list_users_and_teams, never guessed. Formats by column type: text and numbers: "value". long_text: {"text": "..."}. status: {"label": "Done"} or {"index": 1}, and the label must already exist unless createLabelsIfMissing is true. dropdown: {"labels": ["A"]} or {"ids": [1]} — always an array, even for one value. date: {"date": "YYYY-MM-DD"}. timeline: {"from": "YYYY-MM-DD", "to": "YYYY-MM-DD"}. people: {"personsAndTeams": [{"id": 123, "kind": "person"}]}, where kind is "person", "team" or "agent". An AI agent takes kind "agent" with its user id from list_users_and_teams, never "person". board_relation: {"item_ids": [123]}. tags: {"tag_ids": [123]}. checkbox: {"checked": "true"}. link: {"url": "https://...", "text": "..."}. location: {"lat": "40.7", "lng": "-74.0", "address": "..."}, lat and lng are required strings, an address alone fails. email: {"email": "a@b.com", "text": "a@b.com"}. phone: {"phone": "+12125551234", "countryShortName": "US"}, digits only with an optional leading + and no spaces or dashes, uppercase ISO-2 country code. Plain strings fail for email and phone. null clears a column. Example: {"text_col": "New text", "status_col": {"label": "Done"}, "dropdown_col": {"labels": ["A"]}, "date_col": {"date": "2023-05-25"}}
columnValues?: string, // default: "{}"
// When true, missing status or dropdown labels referenced in this update columnValues are auto-created on the board instead of erroring with ColumnValueException. Requires permission to change board structure.
createLabelsIfMissing?: boolean,
// Required. The id of the item to update.
itemId?: number,
}
>,
}): Promise<unknown>;
